PARTIAL INDEX CREATE UNIQUE INDEX dispatch_one_accepted_offer_idx
    ON zippy.dispatch_offers (platform_id, order_id)
    WHERE status = 'accepted';

PARTIAL INDEX CREATE UNIQUE INDEX trip_active_vehicle_idx
    ON zippy.trip_assignments (platform_id, vehicle_id)
    WHERE released_at IS NULL;

PARTIAL INDEX CREATE UNIQUE INDEX trip_active_driver_idx
    ON zippy.trip_assignments (platform_id, driver_profile_id)
    WHERE released_at IS NULL;
